import {events,metadata} from './data.js';
import {defaults,tiers,weekOf,weekEnd,filterEvents,rankEvents,countStats,toCsv,validateDataset} from './model.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#detail');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusLabel={provided:'资料待复核',confirmed:'证据已确认',pending:'待交叉核验',conflicting:'字段冲突'};
const regionLabel={UNKNOWN:'地域未明确',CHINA:'中国',OVERSEAS:'海外'};
const tierLabels={P1:'具身智能核心',P2:'关键部件与相邻技术',P3:'其他硬科技'};
const currencyLabel={CNY_REFERENCE:'人民币参考',HKD:'港元',USD:'美元',EUR:'欧元',CNY:'人民币'};
const weeks=[...new Set(events.map(e=>e.week||weekOf(e.date)))].sort().reverse();
let state={...defaults},view='weekly',lastDetailButton=null;
function readRoute(){const [raw='weekly',query='']=location.hash.slice(1).split('?');view=['weekly','dashboard','archive','methodology'].includes(raw)?raw:'weekly';const p=new URLSearchParams(query);state={...defaults};for(const key of Object.keys(defaults)){if(p.has(key))state[key]=p.get(key)}if(!['ALL',...weeks].includes(state.week))state.week='ALL';if(!['ALL',...tiers].includes(state.tier))state.tier='ALL';if(!['ALL','CHINA','OVERSEAS','UNKNOWN'].includes(state.region))state.region='ALL';if(!['ALL','confirmed','pending','conflicting','provided'].includes(state.status))state.status='ALL';if(!['CNY_REFERENCE','USD','EUR','CNY','HKD'].includes(state.currency))state.currency='USD';if(!['recent','company'].includes(state.sort))state.sort='recent';state.query=state.query.slice(0,300)}
function syncRoute(){const p=new URLSearchParams();for(const [key,value]of Object.entries(state))if(value!==defaults[key])p.set(key,value);history.replaceState(null,'',`#${view}${p.size?'?'+p:''}`)}
function weekLabel(w){return `${w.replaceAll('-','.')} — ${weekEnd(w).slice(5).replace('-','.')}`}
const opt=(value,label,selected)=>`<option value="${esc(value)}"${value===selected?' selected':''}>${esc(label)}</option>`;
function select(name,label,options){return `<label>${label}<select name="${name}">${options.map(([v,l])=>opt(v,l,state[name])).join('')}</select></label>`}
function toolbar(){return `<form class="toolbar" id="filters" role="search">${select('week','公告周次',[['ALL','全部六期'],...weeks.map(w=>[w,weekLabel(w)])])}${select('tier','相关度',[['ALL','全部层级'],...tiers.map(t=>[t,`${t} · ${tierLabels[t]}`])])}${select('region','地域',[['ALL','全部地域'],['CHINA','中国'],['OVERSEAS','海外']])}${select('status','核验状态',[['ALL','全部状态'],['provided','资料待复核'],['confirmed','本站已确认']])}<label class="search">搜索<input name="query" type="search" value="${esc(state.query)}" placeholder="公司、业务、投资机构" autocomplete="off"></label><button type="button" data-action="reset">重置</button></form>`}
function metrics(rows){const s=countStats(rows);return `<div class="metrics">${[['当前记录',s.total,'按原周报期次与筛选统计'],['已披露金额',s.disclosed,'含金额描述 · 非金额合计'],['中国公司事件',s.china,`海外 ${rows.filter(e=>e.region==='OVERSEAS').length} 条 · 未明确 ${rows.filter(e=>e.region==='UNKNOWN').length} 条`],['来源链接',rows.filter(e=>e.sourceUrl).length,'公开资料 · 尚未独立复核']].map(([label,value,note])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value.toString().padStart(2,'0')}</div><div class="metric-note">${note}</div></div>`).join('')}</div>`}
function tags(e){return `<div class="tags"><span class="tag tier">${e.tier} · ${esc(e.sector)}</span><span class="tag">${regionLabel[e.region]}</span><span class="tag${e.status==='confirmed'?' verified':''}">${statusLabel[e.status]}</span></div>`}
function card(e){return `<article class="card"><div class="card-head"><div class="company-line"><span class="company-monogram" aria-hidden="true">${esc(e.company.slice(0,1))}</span><div><h3>${esc(e.company)}</h3><span class="company-meta">${esc(e.date||'公告日期未明确')} · ${esc(e.round)}</span></div></div><div class="amount">${esc(e.amountText)}<small>${e.dealType==='acquisition'?'并购事件':'原始披露口径'}</small></div></div><p>${esc(e.summary)}</p>${tags(e)}<div class="card-bottom"><span>${e.investors.length?'投资方 · '+esc(e.investors.slice(0,2).join('、')):'投资方 · 当前证据未完整列示'}</span><div><button class="text-button" data-detail="${esc(e.id)}">事件详情</button><a class="text-button" href="${esc(e.sourceUrl)}" target="_blank" rel="noopener noreferrer">来源 ↗</a></div></div></article>`}
function empty(message='没有符合条件的记录'){return `<div class="empty"><h3>${message}</h3><p>尝试切换周次、地域或清除搜索条件。没有记录不代表该时期没有融资。</p><button class="outline" data-action="reset">清除筛选</button></div>`}
function sidebar(rows){const s=countStats(rows);return `<aside><div class="side-panel"><h3>相关度分层</h3><div class="tier-row"><strong>P1</strong><p>机器人整机、具身模型与核心系统</p></div><div class="tier-row"><strong>P2</strong><p>核心部件、数据、仿真及相邻技术</p></div><div class="tier-row"><strong>P3</strong><p>其他硬科技资本动态</p></div><a class="mini-link" href="#methodology">阅读完整收录标准 →</a></div><div class="side-panel"><h3>本次阅读范围</h3><p>${state.week==='ALL'?'六期周报合集':weekLabel(state.week)}<br>当前 ${s.total} 条 · 待独立复核 ${s.provided} 条</p><p>沿用公开周报资料。原融资状态不等于本站已完成事实核验。</p></div><div class="side-panel"><h3>更新状态</h3><p>数据接入 · ${metadata.checkedAt}<br>自动采集尚未接入。</p><p>已接入 ${events.length} 条周报记录，覆盖 2026.08.03—09.13；不是当前周实时资讯。</p></div></aside>`}
function table(rows){if(!rows.length)return empty();return `<div class="table-wrap"><table><thead><tr><th scope="col">公司 / 公告日期</th><th scope="col">相关度 / 地域</th><th scope="col">轮次</th><th scope="col">原始金额</th><th scope="col">投资方</th><th scope="col">证据状态</th><th scope="col">来源</th></tr></thead><tbody>${rows.map(e=>`<tr><th scope="row"><button class="text-button" data-detail="${esc(e.id)}">${esc(e.company)}</button><div class="muted">${e.date||'未明确'}</div></th><td>${e.tier} · ${regionLabel[e.region]}</td><td>${esc(e.round)}</td><td>${esc(e.amountText)}</td><td>${esc(e.investors.join('、')||'未完整列示')}</td><td>${statusLabel[e.status]}</td><td><a href="${esc(e.sourceUrl)}" target="_blank" rel="noopener noreferrer">原文 ↗</a></td></tr>`).join('')}</tbody></table></div>`}
function weekly(rows){return `${toolbar()}<div id="results">${weeklyResults(rows)}</div>`}
function weeklyResults(rows){return `${metrics(rows)}<div class="section-head"><div><h2>${state.week==='ALL'?'资本动态 · 六期总览':weekLabel(state.week)}</h2><p>具身智能重点事件与上下游融资</p></div><button class="outline" data-action="print">打印 / 保存 PDF</button></div><div class="content-grid"><div>${rows.length?tiers.filter(t=>rows.some(e=>e.tier===t)).map(t=>`<div class="section-head"><h2>${t} <span style="font-weight:400">${tierLabels[t]}</span></h2><small>${rows.filter(e=>e.tier===t).length} 条</small></div>${t==='P3'?table(rows.filter(e=>e.tier===t)):`<div class="cards">${rows.filter(e=>e.tier===t).map(card).join('')}</div>`}`).join(''):empty()}</div>${sidebar(rows)}</div>`}
function chartRow(name,value,max,label){return `<div class="chart-row"><span>${esc(name)}</span><div class="bar-track"><div class="bar-fill" style="width:${max?value/max*100:0}%"></div></div><b>${esc(label)}</b></div>`}
function dashboard(rows){return `${toolbar()}<div id="results">${dashboardResults(rows)}</div>`}
function dashboardResults(rows){const ranked=rankEvents(rows,state.currency);const exact=rows.filter(e=>['confirmed','provided'].includes(e.status)&&e.completed!==false&&e.dealType==='equity'&&e.amountKind==='exact');const totals=['USD','EUR','CNY','HKD'].map(c=>{const subset=exact.filter(e=>e.currency===c);return subset.length?`${currencyLabel[c]} ${(subset.reduce((s,e)=>s+e.amount,0)/100000000).toLocaleString('zh-CN',{maximumFractionDigits:2})} 亿`:null}).filter(Boolean);return `${metrics(rows)}<div class="dashboard-grid"><section class="panel"><div class="section-head" style="margin-top:0"><h2>单轮融资参考 TOP 10</h2><label class="muted">币种 <select name="currency" aria-label="榜单币种">${['CNY_REFERENCE','USD','EUR','CNY','HKD'].map(c=>opt(c,currencyLabel[c],state.currency)).join('')}</select></label></div><p class="muted">随全部筛选联动 · 资料待复核，非正式核验统计</p>${ranked.length?ranked.map(e=>chartRow(e.company,state.currency==='CNY_REFERENCE'?e.curatedRanking.cnyAmount:e.amount,state.currency==='CNY_REFERENCE'?ranked[0].curatedRanking.cnyAmount:ranked[0].amount,state.currency==='CNY_REFERENCE'?e.curatedRanking.normalizedAmount:`${(e.amount/100000000).toLocaleString('zh-CN',{maximumFractionDigits:2})} 亿`)).join(''):'<p class="empty">本条件下暂无可比金额。模糊金额、待核实及并购事件不进入排名。</p>'}<p class="muted">${state.currency==='CNY_REFERENCE'?'人民币参考沿用 08.24、08.31、09.07 三期国内榜单，各期采用其原汇率日期，保留近／超等限定词，不代表同日精确换算。切换原币种可查看其他记录。':'原币种排名只使用明确数字的已完成股权融资；累计、多轮及模糊金额不纳入。'}</p></section><section class="panel"><h2>相关度分布</h2><p class="muted">研究分类，不代表公司质量或投资价值</p>${tiers.map(t=>chartRow(`${t} · ${tierLabels[t]}`,rows.filter(e=>e.tier===t).length,Math.max(1,rows.length),`${rows.filter(e=>e.tier===t).length} 条`)).join('')}<hr style="border:0;border-top:1px solid var(--line)"><p class="muted">披露金额参考合计 · 待复核 · 按币种分列</p><div class="legend">${totals.length?totals.map(t=>`<span>${t}</span>`).join(''):'<span>暂无符合口径的金额</span>'}</div><p class="muted">“超”“近”等限定金额不参与精确合计；未披露金额不记为零。</p></section></div><div class="table-top"><div><h2>融资与资本事件明细</h2><p class="muted">${rows.length} 条记录 · 点击公司查看证据</p></div><button class="outline" data-action="export"${rows.length?'':' disabled'}>导出 CSV</button></div>${table(rows)}`}
function archive(){return `<div class="section-head"><div><h2>历史归档</h2><p>按原周报期次归档 · 共 ${weeks.length} 期公开数据</p></div></div><div class="archive-grid">${weeks.map(w=>{const r=events.filter(e=>(e.week||weekOf(e.date))===w);return `<a class="archive-card" href="#weekly?week=${w}"><p class="eyebrow">WEEKLY RESEARCH</p><h3>${weekLabel(w)}</h3><p>${r.length} 条记录 · ${r.filter(e=>e.region==='CHINA').length} 条中国公司事件</p><p>${esc(r.map(e=>e.company).slice(0,3).join(' / '))}</p><span>打开该周记录 →</span></a>`}).join('')}</div>`}
function methodology(){return `<article class="method"><h2>什么值得收录</h2><p>围绕人形机器人、具身模型、机器人部件、数据与仿真，以及相关融资、并购和产业落地收集线索。优先保留相关候选，再核验证据、判断重要性；不收录无关日常内容或没有来源支持的 AI 事实。</p><div class="panel"><h2 style="margin-top:0">发布规则 · v1.0</h2><p>当前页面沿用六期公开周报资料，尚未逐条独立复核。以下为后续自动处理使用的规则，当前未连接采集器、模型服务或定时发布。</p><div class="legend"><span>相关性 ≥ 70</span><span>影响力 ≥ 60</span><span>通过证据门槛</span><span>无冲突 / 风险</span></div></div><h2>证据先于分数</h2><div class="table-wrap"><table><thead><tr><th>级别</th><th>来源</th><th>处理规则</th></tr></thead><tbody><tr><td>A · 90–100</td><td>官方公告、论文原文、监管披露</td><td>字段与实体校验通过后可支持确认</td></tr><tr><td>B · 75–89</td><td>具有采编与纠错机制的媒体</td><td>两个独立证据链可支持确认</td></tr><tr><td>C · 55–74</td><td>自媒体、已验证个人账号</td><td>保留线索，需进一步核验</td></tr><tr><td>D · 0–54</td><td>匿名、转载或来源链不明</td><td>仅作待核实候选</td></tr></tbody></table></div><p>多家网站转载同一篇报道仍属于一条证据链。来源级别按原始发布者判定，不能仅凭“发布在通讯社平台”就认定为官方。当前导入记录未重新评级，全部标为资料待复核。</p><h2>六项评分，分别留存</h2><p>相关性 25% · 事件影响 25% · 来源可信度 20% · 新颖性 10% · 重点关注相关性 10% · 多来源验证 10%。综合分用于排序，不能抵消证据冲突。未评分的记录不显示虚构分数。</p><h2>融资统计的边界</h2><ul><li>保留原始金额、币种、限定词与公告日期。</li><li>人民币参考榜沿用原周报榜单及其汇率日期；原币种榜只比较同币种金额。</li><li>参考榜不等同于本站已核验统计。原币种榜排除模糊金额，人民币参考榜保留原榜单的近／超限定词；所有筛选共同驱动结果。</li><li>并购、债务、补贴、IPO 与股权融资分开；累计金额不混入单轮榜单。</li><li>模糊金额与资本承诺保留原文说明；未披露不是零。</li><li>归档保留原周报期次，不改变来源公告日期，不推断交割日期。</li></ul><h2>覆盖与维护</h2><p>本版本于 ${metadata.checkedAt} 接入六期 ${events.length} 条公开周报记录，摘要、分类、金额及来源沿用已导入资料。这些记录不是当前周新闻、全市场清单或最新融资情况。地域与 P1/P2/P3 为研究分类。</p><p>新增记录通过数据校验后发布。持续采集、审核后台、飞书推送和定时 PDF 尚未接通，当前支持浏览器打印或保存 PDF。</p></article>`}
function render(){document.querySelectorAll('[data-view]').forEach(a=>{if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const heading={weekly:['看见具身智能的资本动向','从融资事件出发，追踪公司、技术与产业进展。'],dashboard:['融资数据，按你的视角展开','让每一个数字，都有清晰的来源与统计边界。'],archive:['每周记录，持续积累','以公告时间为线索，回看具身智能与硬科技的资本动态。'],methodology:['先看证据，再做判断','收录范围、核验门槛与金额口径，公开可查。']}[view];document.querySelector('h1').textContent=heading[0];document.querySelector('.intro>p:last-child').textContent=heading[1];document.title=`${{weekly:'行业周报',dashboard:'融资数据',archive:'历史归档',methodology:'收录标准'}[view]} · 具身投资观察`;const rows=filterEvents(events,state);app.innerHTML=view==='weekly'?weekly(rows):view==='dashboard'?dashboard(rows):view==='archive'?archive():methodology();}
function updateResults(){syncRoute();const rows=filterEvents(events,state);const results=document.querySelector('#results');if(results)results.innerHTML=view==='weekly'?weeklyResults(rows):dashboardResults(rows)}
function openDetail(id,button){const e=events.find(row=>row.id===id);if(!e)return;lastDetailButton=button;document.querySelector('#detail-content').innerHTML=`<p class="eyebrow">EVENT / SOURCE RECORD</p><h2 id="detail-title">${esc(e.company)}</h2>${tags(e)}<p>${esc(e.summary)}</p><dl><dt>公告日期</dt><dd>${e.date||'未明确'}</dd><dt>轮次 / 类型</dt><dd>${esc(e.round)}</dd><dt>披露金额</dt><dd>${esc(e.amountText)}</dd><dt>投资方</dt><dd>${esc(e.investors.join('、')||'当前证据未完整列示')}</dd><dt>来源等级</dt><dd>${e.grade==='UNRATED'?'本站未评级':e.grade} · ${statusLabel[e.status]}</dd></dl><div class="notice">${esc(e.note)}</div><h3>原始来源</h3>${(e.sources||[{url:e.sourceUrl,publishedAt:e.date}]).map((source,i)=>`<p><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">来源 ${i+1} · ${esc(new URL(source.url).hostname)} ↗</a> <span class="muted">${esc(source.publishedAt||'日期未明确')}</span></p>`).join('')}<p class="muted">摘要与分类沿用已导入周报资料，新闻原始出处如下；本站尚未重新核验。</p>`;dialog.setAttribute('aria-labelledby','detail-title');dialog.showModal();}
app.addEventListener('submit',e=>e.preventDefault());
app.addEventListener('input',e=>{if(e.target.name==='query'){state.query=e.target.value.slice(0,300);updateResults()}});
app.addEventListener('change',e=>{if(Object.hasOwn(defaults,e.target.name)){state[e.target.name]=e.target.value;updateResults()}});
app.addEventListener('click',e=>{const detail=e.target.closest('[data-detail]');if(detail){openDetail(detail.dataset.detail,detail);return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='reset'){state={...defaults};syncRoute();render()}if(action==='print')window.print();if(action==='export'){const blob=new Blob([toCsv(filterEvents(events,state))],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`embodied-investment-${state.week==='ALL'?'archive':state.week}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
document.querySelector('#close-detail').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>lastDetailButton?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
window.addEventListener('hashchange',()=>{readRoute();render();window.scrollTo({top:0,behavior:'instant'})});
try{validateDataset(events);readRoute();render()}catch(error){app.textContent='研究数据未通过校验，暂时无法展示。';console.error(error)}
const context=document.modelContext;
if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'filter_investment_events',title:'筛选投资情报',description:'将页面切换至融资面板并设置筛选，返回当前记录与同币种榜单；不修改研究数据。',inputSchema:{type:'object',properties:{query:{type:'string'},tier:{type:'string',enum:['ALL','P1','P2','P3']},region:{type:'string',enum:['ALL','CHINA','OVERSEAS','UNKNOWN']},week:{type:'string'},currency:{type:'string',enum:['CNY_REFERENCE','USD','EUR','CNY','HKD']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['query','tier','region','week','currency'].includes(k)))throw Error('未知筛选字段');if(Object.values(input).some(v=>typeof v!=='string'))throw Error('筛选值须为文本');if(input.query?.length>300||input.tier&&!['ALL',...tiers].includes(input.tier)||input.region&&!['ALL','CHINA','OVERSEAS','UNKNOWN'].includes(input.region)||input.week&&!['ALL',...weeks].includes(input.week)||input.currency&&!['CNY_REFERENCE','USD','EUR','CNY','HKD'].includes(input.currency))throw Error('筛选值无效');state={...defaults,...input};view='dashboard';syncRoute();render();const rows=filterEvents(events,state);return {count:rows.length,companies:rows.map(e=>e.company),ranking:rankEvents(rows,state.currency).map(e=>({company:e.company,amount:state.currency==='CNY_REFERENCE'?e.curatedRanking.normalizedAmount:e.amountText,currency:state.currency,verification:e.status}))}}})).catch(()=>{});}catch{}}
